INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-shore-stone', 'east', 'the-shore-descent', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shore-descent', 'door', 'The Shore Descent', 'The track leaves the bench and goes down off the moor in long shallow zigzags, losing the height it spent all morning gaining. The water gets bigger the whole way down, which is not how distance is supposed to work, and by the bottom of it you cannot see the far side without turning your head.', 0, 0, 'crossing', 0, 44, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shore-descent', 'west', 'the-far-shore-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shore-descent', 'east', 'the-strand-head', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-strand-head', 'door', 'The Strand Head', 'The moor ends and the shore begins in one step: peat, then shingle, then water, with nothing in between to soften it. The stones are round and grey and go down to the tideline in a bank you sink into to the ankle. Everything smells of cold water and weed.', 0, 0, 'crossing', 0, 45, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-head', 'west', 'the-shore-descent', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-head', 'east', 'the-shore-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-head', 'south', 'the-wrack-line', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wrack-line', 'door', 'The Wrack Line', 'A long ragged windrow of everything the water has finished with: weed in ropes, a shoe, bird bone, a stave, a fishing float gone brittle. It runs the whole length of the shore and it is different every time the water comes up. People walk this line for a living. You can see where they have turned things over.', 0, 0, 'crossing', 0, 45, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wrack-line', 'north', 'the-strand-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wrack-line', 'east', 'the-net-poles', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wrack-line', 'west', 'the-boat-noust', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-net-poles', 'door', 'The Net Poles', 'Twenty stakes driven in a curve out into the shallows, black with age and still standing, with the last shreds of a net on the nearest three. A fixed engine: the tide brought the fish in and the net kept them when it went out. It caught nothing this morning. It has caught nothing for a long time.', 0, 0, 'crossing', 0, 46, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-net-poles', 'west', 'the-wrack-line', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-net-poles', 'north', 'the-shore-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-net-poles', 'south', 'the-shellfish-scars', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shore-road', 'door', 'The Shore Road', 'A made road running north to south along the top of the shingle, above the highest tide-mark and below the moor — the road that serves the crossings rather than making one. Everything on this bank is on it. It is in better repair than it has any right to be.', 0, 0, 'crossing', 0, 46, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shore-road', 'west', 'the-strand-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shore-road', 'south', 'the-net-poles', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shore-road', 'east', 'the-parting', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hard', 'door', 'The Hard', 'A ramp of laid stone going down into the water at a shallow angle, wide enough for a cart, grooved by keels. This is where boats were taken out and put in. The stone below the waterline is furred green and the stone above it is worn white, and the line between them is the most legible thing on this shore.', 0, 0, 'crossing', 0, 47, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hard', 'north', 'the-ferry-house', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hard', 'south', 'the-capstan-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hard', 'east', 'the-ferry-steps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-capstan-stone', 'door', 'The Capstan Stone', 'A block of dressed stone set flush in the road with a square socket cut through the middle of it, and the socket is worn round. A capstan stood here and boats were hauled up past it, and the road runs on over it now as if it were paving, because that is what it has become.', 0, 0, 'crossing', 0, 47, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-capstan-stone', 'north', 'the-hard', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-capstan-stone', 'south', 'the-tide-mark', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ferry-house', 'door', 'The Ferry House', 'A stone house with a wide door facing the water and a stove-in boat under the lean-to, and a window that looks straight down the deep channel to the far bank. Somebody lived here to take people over, and their whole working life was one distance, repeated. The rope-drum is still bolted to the floor — and there is a lamp burning over a hatch in the road-facing wall, and the same arrangement holds here as holds on the other side, and the keeper behind the hatch does not explain it either.', 1, 1, 'crossing', 0, 47, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferry-house', 'north', 'the-rope-walk', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferry-house', 'south', 'the-hard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-rope-walk', 'door', 'The Rope Walk', 'A long level strip beside the road, fenced on both sides, running perfectly straight for further than anything here needs to be. Rope was laid out and twisted down its length, and the ferry rope was made on it, and it is the only piece of ground on this shore that was flattened on purpose.', 0, 0, 'crossing', 0, 47, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rope-walk', 'north', 'the-bridge-approach', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rope-walk', 'south', 'the-ferry-house', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-parting', 'door', 'The Parting of the Ways', 'The shore road widens where the five ways separate, and there is a fingerpost in the middle of it with five arms, and it is the single most important object in this country. Four of the arms point north up the shore road, at different heights, for the four different distances; the fifth points east, straight down the causeway, and is the shortest arm on the post.', 0, 0, 'crossing', 0, 47, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-parting', 'west', 'the-shore-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-parting', 'east', 'the-causeway-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-parting', 'north', 'the-tide-mark', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-parting', 'south', 'the-eyot-track', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-causeway-head', 'door', 'The Causeway Head', 'The made road runs out onto a bank of piled stone and simply keeps going, out into the water, dead straight, until distance takes it. On the last dry stone there is a marked post: a scale of cut lines up its length, the top one well above your head, and every line has a hand''s-breadth of weed dried onto it.', 0, 0, 'crossing', 0, 48, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-causeway-head', 'west', 'the-parting', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-causeway-head', 'east', 'the-first-crossing-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bridge-approach', 'door', 'The Bridge Approach', 'The road climbs onto an embankment and aims itself at the bridge, and from up here you can see the whole shape of the problem: four piers standing in the water, an arch on this end, an arch on the far end, and a very great deal of nothing in between them.', 0, 0, 'crossing', 0, 47, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bridge-approach', 'south', 'the-rope-walk', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bridge-approach', 'east', 'the-near-arch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bridge-approach', 'north', 'the-toll-post', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ford-road', 'door', 'The Ford Road', 'The road north along the shore, above the water, running toward where the crossing widens and shallows. It is the least travelled of the five and the surface says so: grass down the middle, and the verges closing in on both sides.', 0, 0, 'crossing', 0, 47, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ford-road', 'south', 'the-quay-stub', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ford-road', 'north', 'the-gravel-flats', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-eyot-track', 'door', 'The Eyot Track', 'A path leaving the shore road southward and going down into the reeds, made of whatever came to hand — brushwood, a laid stone, a plank on two stones — and repaired by different people at different times with different ideas about how much effort this was worth.', 0, 0, 'crossing', 0, 47, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyot-track', 'north', 'the-parting', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eyot-track', 'south', 'the-reed-gate', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ferry-steps', 'door', 'The Ferry Steps', 'Cut steps going down the bank into the water, with an iron ring at the top of them and the ferry rope through the ring, and the rope going out level across the channel and disappearing into its own reflection. The rope is taut. Something is holding the other end.', 0, 0, 'crossing', 0, 48, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferry-steps', 'west', 'the-hard', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferry-steps', 'east', 'the-rope-stage', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-rope-stage', 'door', 'The Rope Stage', 'A timber stage out over the deep water where the ferry came alongside, with a bollard, a fend-off post, and the rope running through a block that still turns. From out here the channel shows its colour: not grey like the shallows. Green, and then not green.', 0, 0, 'crossing', 0, 49, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rope-stage', 'west', 'the-ferry-steps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rope-stage', 'east', 'the-channel-brink', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gravel-flats', 'door', 'The Gravel Flats', 'North of the crossings the water spreads and thins and loses its authority, running over banks of grey gravel that stand clear at low water and go under at high. The channels between them shift with every tide. You can see the ford from here, or where it usually is.', 0, 0, 'crossing', 0, 47, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gravel-flats', 'south', 'the-ford-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gravel-flats', 'east', 'the-ford-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gravel-flats', 'north', 'the-mussel-scaup', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-mussel-scaup', 'door', 'The Mussel Scaup', 'A bed of them on the gravel, acres of it, blue-black and packed edge to edge and every shell shut. It goes out further than you would want to walk and it is under water half the time. Somebody has raked a path through the middle of it, and the path is old, and the mussels have not closed it up.', 0, 0, 'crossing', 0, 47, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mussel-scaup', 'south', 'the-gravel-flats', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-reed-gate', 'door', 'The Reed Gate', 'The reeds close over the track and the light goes green and the sound of open water stops as if a door had shut. This is the way into the eyots and the reeds are twice a man''s height on both sides, and the path underfoot is somebody''s brushwood, and it gives.', 0, 0, 'crossing', 0, 47, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-reed-gate', 'north', 'the-eyot-track', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-reed-gate', 'south', 'the-first-eyot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-near-arch', 'door', 'The Near Arch', 'The one span still standing on this side. You walk up onto the bridge under a proper arch on proper piers, over water that is suddenly a long way down, and it is the best piece of building in this country. It ends forty feet out, in a clean broken edge, above the channel.', 0, 0, 'crossing', 0, 48, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-near-arch', 'west', 'the-bridge-approach', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-near-arch', 'east', 'the-first-pier', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-first-crossing-stone', 'door', 'The First Crossing Stone', 'The causeway proper: a road two carts wide on a bank of piled and pinned stone, running east into the water. The surface is sound. The weed on it is combed all one way, flat, and it is wet, and there is no rain.', 0, 0, 'crossing', 0, 49, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-crossing-stone', 'west', 'the-causeway-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-crossing-stone', 'east', 'the-weeded-milestone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-channel-brink', 'door', 'The Channel Brink', 'The end of the stage, where the timber stops and the deep starts. The water here does not show a bottom at any angle you try. The ferry rope goes out over it, dipping to touch the surface halfway across and coming up again on the far side, and whatever the rope is fast to over there is not visible.', 0, 0, 'crossing', 0, 50, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-channel-brink', 'west', 'the-rope-stage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-channel-brink', 'east', 'the-rope-run', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-tide-mark', 'door', 'The Tide Mark', 'A post set in the shingle above the strand, taller than a man, with a scale cut up it and a bracket at the top for a lantern that is not there. This is how the shore reads the water: one glance, and you know which of the five ways is a way today. Somebody has kept the cut lines clear of weed.', 0, 0, 'crossing', 0, 47, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tide-mark', 'north', 'the-capstan-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tide-mark', 'south', 'the-parting', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boat-noust', 'door', 'The Boat Noust', 'A boat-shaped hollow dug into the bank above the tide and lined with stone, where a small boat was pulled up out of the weather for the winter. It is empty. It is exactly the right shape to tell you what is missing from it, which is a boat.', 0, 0, 'crossing', 0, 44, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boat-noust', 'east', 'the-wrack-line', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-weeded-milestone', 'door', 'The Drowned Milestone', 'A milestone on the causeway, standing in its socket like all the others, weeded to the waist and legible above that: a number, and a direction, cut by the same hand as every milestone on the east road. Whoever built this considered it a road. It is a road. It is simply also, for part of every day, the bottom of the water.', 0, 0, 'crossing', 0, 50, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-weeded-milestone', 'west', 'the-first-crossing-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-weeded-milestone', 'east', 'the-causeway-bend', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shellfish-scars', 'door', 'The Shellfish Scars', 'Flat rock running out into the shallows, gouged all over with old rectangular cuts where stone was quarried off the shore itself. The pits hold water and the water holds things. Limpets, weed, and one crab going about its business with no interest in yours.', 0, 0, 'crossing', 0, 46, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shellfish-scars', 'north', 'the-net-poles', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-quay-stub', 'door', 'The Quay Stub', 'Twelve feet of proper dressed quay, and then nothing — the rest of it went into the water at some point and was never rebuilt, and you can see the courses of it down there, square-cut and green. A ring bolt at the end still stands proud, and there is a new rope on it, and the rope goes down into the water.', 0, 0, 'crossing', 0, 47, 2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quay-stub', 'north', 'the-ford-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quay-stub', 'south', 'the-toll-post', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-toll-post', 'door', 'The Toll Post', 'A stone post at the side of the road with a table of charges cut into it, weathered down to the columns: a man, a man and a beast, a cart, a cart laden. The figures are gone. What survives is the shape of an argument about how much crossing this water was worth, and to whom.', 0, 0, 'crossing', 0, 47, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-toll-post', 'north', 'the-quay-stub', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-toll-post', 'south', 'the-bridge-approach', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-causeway-bend', 'door', 'The Causeway Bend', 'The only bend in the whole thing, and it is here because the bank of shingle under it is here — the builders followed the one natural ridge in the crossing and took the dogleg rather than pay for the straight line. Weed lies combed flat along the road, all pointing the same way, which is the way the water goes out.', 0, 0, 'crossing', 0, 51, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-causeway-bend', 'west', 'the-weeded-milestone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-causeway-bend', 'east', 'the-half-tide-post', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-half-tide-post', 'door', 'The Half-Tide Post', 'A post set in the causeway''s edge with a broad white band painted round it, and the band is at knee height. Everything you need to know is in where the water is against that band. Below it, you have time. On it, you are already deciding. Above it, the decision was made for you a while ago.', 0, 0, 'crossing', 0, 52, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-half-tide-post', 'west', 'the-causeway-bend', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-half-tide-post', 'east', 'the-second-crossing-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-second-crossing-stone', 'door', 'The Second Crossing Stone', 'Another milestone, weeded to the same height as the first, cut by the same hand, counting a distance that made sense to a man with a cart on a dry road. Barnacle on the north face and none on the south, which tells you which way the weather comes from out here.', 0, 0, 'crossing', 0, 53, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-crossing-stone', 'west', 'the-half-tide-post', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-crossing-stone', 'east', 'the-sunken-stretch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sunken-stretch', 'door', 'The Sunken Stretch', 'The causeway dips. Not much — a foot, maybe two, over forty yards — but it is the lowest part of the whole crossing and it is standing in water when the rest of the road is dry. You wade it every time. It is where everybody learns that the causeway is not a road, it is a bargain.', 0, 0, 'crossing', 0, 54, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunken-stretch', 'west', 'the-second-crossing-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunken-stretch', 'east', 'the-drain-arch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunken-stretch', 'north', 'the-crab-pools', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-drain-arch', 'door', 'The Drain Arch', 'A low arch built through the causeway to let the water pass rather than pile against it — the one piece of humility in the design. The water goes through it fast, both ways, twice a day, and it has been doing that long enough to polish the stone inside to a shine you can see your hand in.', 0, 0, 'crossing', 0, 55, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drain-arch', 'west', 'the-sunken-stretch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drain-arch', 'east', 'the-mid-causeway', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drain-arch', 'south', 'the-lantern-stump', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drain-arch', 'north', 'the-sluice-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-mid-causeway', 'door', 'The Mid-Causeway', 'Halfway, and there is nothing here but road and water and the fact that you are a long way from either end. Both shores are equally far and equally small. Whatever you decided on the strand you are now committed to, and the post back there is too distant to read.', 0, 0, 'crossing', 0, 56, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-causeway', 'west', 'the-drain-arch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-causeway', 'east', 'the-refuge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-causeway', 'north', 'the-half-drowned-cart', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-refuge', 'door', 'The Refuge', 'A stone platform built out from the causeway''s side, six feet up on its own little pier, with three steps and a rail-socket and room for four people to stand. It is here because the builders knew people would misjudge it. Somebody has cut a tally into the top step, and it is a long tally.', 0, 1, 'crossing', 0, 57, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-refuge', 'west', 'the-mid-causeway', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-refuge', 'east', 'the-far-milestone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-refuge', 'south', 'the-causeway-cross', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-far-milestone', 'door', 'The Far Milestone', 'The third milestone, and this one is not weeded — it stands above the highest of it, and the cut face is clean and grey and reads perfectly. From here on the causeway climbs, imperceptibly, all the way to the far shore. The worst is behind you, which you can only know by having got here.', 0, 0, 'crossing', 0, 58, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-milestone', 'west', 'the-refuge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-milestone', 'east', 'the-mussel-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-mussel-bank', 'door', 'The Mussel Bank', 'The causeway''s stone has been colonised: mussel packed edge to edge over the whole northern face and out onto the road itself, so the walking surface is shell, and shell breaks, and the edges of it are exactly as sharp as they look.', 0, 0, 'crossing', 0, 59, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mussel-bank', 'west', 'the-far-milestone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mussel-bank', 'east', 'the-cutting-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mussel-bank', 'south', 'the-wreck-ribs', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cutting-water', 'door', 'The Cutting Water', 'A channel crosses the causeway here — a real one, deep enough to have its own current, gouged through the bank by two centuries of the water insisting. Somebody has laid three great slabs across it as a bridge and two of them are still where they were put.', 0, 0, 'crossing', 0, 60, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cutting-water', 'west', 'the-mussel-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cutting-water', 'east', 'the-weed-flat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cutting-water', 'north', 'the-oyster-scars', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cutting-water', 'south', 'the-bell-buoy', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-weed-flat', 'door', 'The Weed Flat', 'Bladderwrack over everything, ankle deep, hiding the road entirely. You find the causeway by feel and by the fact that stepping off it is instantly obvious. In the sun the bladders pop under your boots one at a time, and the sound carries out over the water further than seems reasonable.', 0, 0, 'crossing', 0, 61, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-weed-flat', 'west', 'the-cutting-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-weed-flat', 'east', 'the-causeway-rise', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-weed-flat', 'south', 'the-perch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-causeway-rise', 'door', 'The Causeway Rise', 'The bank lifts out of the weed and becomes a road again, dry, drained, with a proper camber and a verge. The far shore stops being a horizon and becomes a place with things on it. Behind you the whole crossing lies flat and grey and looks like nothing at all.', 0, 0, 'crossing', 0, 62, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-causeway-rise', 'west', 'the-weed-flat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-causeway-rise', 'east', 'the-landing-arch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-landing-arch', 'door', 'The Landing Arch', 'The causeway comes ashore under a stone arch built for no structural reason whatever — the road does not need it and the bank does not need it. It is there so that arriving is an event. The keystone has a face on it, worn to a suggestion, and it is looking back the way you came.', 0, 0, 'crossing', 0, 63, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-landing-arch', 'west', 'the-causeway-rise', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-landing-arch', 'north', 'the-far-parting', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-landing-arch', 'south', 'the-far-strand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-lantern-stump', 'door', 'The Lantern Stump', 'Off the causeway''s edge on a stub of pier, the base of a lamp-standard, snapped off at the collar, with the lead still run into the socket. A light stood here to say where the road was after dark. Nothing says where the road is after dark now.', 0, 0, 'crossing', 0, 55, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lantern-stump', 'north', 'the-drain-arch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-oyster-scars', 'door', 'The Oyster Scars', 'A ledge off the causeway''s south side, exposed at low water, cut all over with the marks of tongs and rakes. This was somebody''s ground and they worked it hard. The shells underfoot go down further than a spade would.', 0, 0, 'crossing', 0, 60, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oyster-scars', 'south', 'the-cutting-water', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wreck-ribs', 'door', 'The Wreck Ribs', 'Off the north side: the frames of a boat, stuck upright in the mud at a slant, black and hard as iron, spaced like ribs because that is what they are. Whatever it was, it was bigger than anything the ferry-house ever ran, and it did not sink here — it was left here.', 0, 0, 'crossing', 0, 59, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wreck-ribs', 'north', 'the-mussel-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-perch', 'door', 'The Perch', 'A wooden beacon on a tripod of legs standing off the causeway in open water, tarred black, with a cage top for a fire. Reachable at low water by a spit of shingle. Nothing has burned in it in living memory and the cage is full of nest.', 0, 0, 'crossing', 0, 61, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-perch', 'north', 'the-weed-flat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-crab-pools', 'door', 'The Crab Pools', 'Rock pools in the causeway''s shelter, deep and clear and cold, with weed hanging into them and things going about their business under the ledges. The pools do not empty when the water goes. They simply become a different, smaller, more concentrated water.', 0, 0, 'crossing', 0, 54, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crab-pools', 'south', 'the-sunken-stretch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sluice-stone', 'door', 'The Sluice Stone', 'A great slab beside the drain arch with a groove cut down each edge — a gate ran in those grooves once, and could be dropped to shut the arch and hold the water on one side. It is not here. The grooves are, and they are worn, so it was used, often, by people who had a reason.', 0, 0, 'crossing', 0, 55, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sluice-stone', 'south', 'the-drain-arch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bell-buoy', 'door', 'The Bell Buoy', 'Aground on the shingle at the causeway''s edge, on its side: an iron float the size of a cow with a cage on top and a bell in the cage, and the bell still has its clapper. It rang on the water for whoever was out in the dark. You could ring it now. Everything for a mile would hear.', 0, 0, 'crossing', 0, 60, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bell-buoy', 'north', 'the-cutting-water', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-half-drowned-cart', 'door', 'The Half-Drowned Cart', 'A cart in the water off the causeway''s south side, up to its bed, one wheel gone and the other still turning a little when the current is running. It is not old. The wood is sound and the ironwork is barely rusted, and whatever was in it is not in it now.', 0, 0, 'crossing', 0, 56, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-half-drowned-cart', 'south', 'the-mid-causeway', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-causeway-cross', 'door', 'The Causeway Cross', 'A stone cross set in the causeway''s verge at the point where you can no longer see either shore clearly, weathered to a stump with the arms gone. People put these where the danger was, or where the dead were, and on a road that drowns twice a day those are the same place.', 0, 0, 'crossing', 0, 57, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-causeway-cross', 'north', 'the-refuge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-first-pier', 'door', 'The First Pier', 'The near arch ends and the first pier begins: a plinth of dressed stone the size of a room, forty feet above green water, with the broken stubs of the arch springing off both sides of it. Somebody has laid a plank to the next one. The plank is not new and it is not thick.', 0, 0, 'crossing', 0, 49, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-pier', 'west', 'the-near-arch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-pier', 'east', 'the-plank-span', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-pier', 'south', 'the-scaffold-stub', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-plank-span', 'door', 'The Plank Span', 'Two planks, side by side, lashed at both ends, spanning the gap between the first pier and the second. They flex. They flex differently depending on where your weight is, which you find out in the middle. Below, the water goes past in a way that makes it very clear how fast it is going.', 0, 0, 'crossing', 0, 50, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plank-span', 'west', 'the-first-pier', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plank-span', 'east', 'the-second-pier', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-second-pier', 'door', 'The Second Pier', 'The second plinth, and there is more standing here: two courses of the arch still curving off eastward before they stop. It is enough to sit under out of the wind, and somebody has, at some length. There is a fire-scar on the stone and a great many fish bones.', 0, 1, 'crossing', 0, 51, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-pier', 'west', 'the-plank-span', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-pier', 'east', 'the-gap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-pier', 'down', 'the-starling', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gap', 'door', 'The Gap', 'The place where the bridge is most emphatically not a bridge. The third pier stands seventy feet off with nothing whatever between here and it except air and, a long way down, the deep channel going through at speed. There is an iron beam laid across it. One beam.', 0, 0, 'crossing', 0, 52, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gap', 'west', 'the-second-pier', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gap', 'east', 'the-beam-walk', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-beam-walk', 'door', 'The Beam Walk', 'You are on the beam. It is eight inches of rusted iron and it is perfectly rigid, which is a mercy, and there is nothing to hold and nothing on either side, which is not. The wind up here has an opinion. Do not look at the water, which is doing something complicated a long way beneath you.', 0, 0, 'crossing', 0, 53, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beam-walk', 'west', 'the-gap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-beam-walk', 'east', 'the-third-pier', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-third-pier', 'door', 'The Third Pier', 'Solid ground, of a sort: the third plinth, wider than the others, with the stump of a tower on it that once carried a gate. There are iron pins in the stone and a windlass drum lying on its side, and the whole arrangement says that people were once stopped here and made to pay.', 0, 0, 'crossing', 0, 54, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-pier', 'west', 'the-beam-walk', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-pier', 'east', 'the-broken-arch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-pier', 'down', 'the-pier-foot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-pier', 'south', 'the-tollhouse-shell', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-pier-foot', 'door', 'The Pier Foot', 'Steps cut down the inside of the third pier to a ledge just above the water, wet, green, and out of the wind. The channel goes past at your feet with real force. There is an iron ring here and a good deal of rope, and the rope goes down, and it is under tension.', 0, 0, 'crossing', 0, 55, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pier-foot', 'up', 'the-third-pier', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-broken-arch', 'door', 'The Broken Arch', 'The arch resumes — half of it, springing east and simply stopping in mid-air with the stones still keyed. You walk out along the top of what is left, which narrows the whole way, until it is one course wide and ends. There is a rope bridge from the end of it to the fourth pier, and it is somebody''s honest work.', 0, 0, 'crossing', 0, 55, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-arch', 'west', 'the-third-pier', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-broken-arch', 'east', 'the-rope-bridge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-rope-bridge', 'door', 'The Rope Bridge', 'Three ropes: one to walk, two to hold, with slats lashed to the walking rope at intervals of somebody''s stride and not yours. It swings. It swings more the further out you get and then less again, and the far end is fast to a ring somebody set in the fourth pier with a great deal of trouble.', 0, 0, 'crossing', 0, 56, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rope-bridge', 'west', 'the-broken-arch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rope-bridge', 'east', 'the-fourth-pier', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fourth-pier', 'door', 'The Fourth Pier', 'The last plinth, and the far arch springs off it whole and lands on the far bank — from here the bridge is a bridge again for its final forty feet, and it is almost insulting how solid it is. Everything hard about this crossing is behind you and it took four piers to learn it.', 0, 0, 'crossing', 0, 57, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fourth-pier', 'west', 'the-rope-bridge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fourth-pier', 'east', 'the-far-arch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fourth-pier', 'down', 'the-drowned-span', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-far-arch', 'door', 'The Far Arch', 'Proper masonry, a proper parapet, a proper roadway, running level onto the far bank. There is a bench in a recess in the parapet, facing back the way you came, so that whoever built this expected people to sit down at this exact point and look at what they had just crossed.', 0, 1, 'crossing', 0, 58, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-arch', 'west', 'the-fourth-pier', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-arch', 'east', 'the-bridge-strand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-tollhouse-shell', 'door', 'The Tollhouse Shell', 'On the third pier''s landward side, the shell of a small building corbelled out over the water on four brackets — one room, one window, one door, and a slot in the floor. Whoever sat in here collected from everyone who crossed, and had nowhere at all to go if it went wrong.', 0, 0, 'crossing', 0, 54, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tollhouse-shell', 'north', 'the-third-pier', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-starling', 'door', 'The Starling', 'Down at the second pier''s foot, the boat-shaped stone apron built to break the current before it reaches the pier itself. It is doing its job. Standing on it, the water piles up against the point and goes round both sides, and the noise is enormous, and there is a great deal caught in the angle.', 0, 0, 'crossing', 0, 52, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-starling', 'up', 'the-second-pier', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-scaffold-stub', 'door', 'The Scaffold Stub', 'Putlog holes in a row across the first pier''s face, square, deliberate, and one of them still has the butt of a timber in it, sound. Somebody was rebuilding this. They got the scaffold up and they went no further, and the rest of the timbers are presumably at the bottom.', 0, 0, 'crossing', 0, 49, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-scaffold-stub', 'north', 'the-first-pier', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-drowned-span', 'door', 'The Drowned Span', 'Reachable at low water down a stair on the fourth pier: the fallen middle of the bridge, lying in the shallows in enormous keyed blocks, exactly in the order it fell, with the arch''s curve still legible in the way they lie. Weed on all of it. You can walk the length of a span that is on its side.', 0, 0, 'crossing', 0, 58, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drowned-span', 'up', 'the-fourth-pier', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ford-head', 'door', 'The Ford Head', 'The shore road ends at a bank of shingle and the crossing opens out in front of it, a mile of grey water over grey gravel with the far side a low smudge. There is no road. There is a line of withies stuck in the gravel going out into it, and they are the ford, and somebody replaces them.', 0, 0, 'crossing', 0, 48, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ford-head', 'west', 'the-gravel-flats', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ford-head', 'east', 'the-first-shoal', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-first-shoal', 'door', 'The First Shoal', 'A bank of gravel standing clear of the water, long and low and curved like a drawn bow, with the current going past both ends of it at different speeds. The withies march up onto it and off the other side. Walking on it is walking on a road made of marbles.', 0, 0, 'crossing', 0, 49, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-shoal', 'west', 'the-ford-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-shoal', 'east', 'the-first-channel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-shoal', 'south', 'the-net-stakes', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-first-channel', 'door', 'The First Channel', 'Between the shoals, the water runs. It is over the boot and under the knee and it is cold enough to be an argument, and it is going sideways hard enough that you lean into it without deciding to. The gravel underfoot moves as you cross. That is normal. It does not stop being alarming.', 0, 0, 'crossing', 0, 50, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-channel', 'west', 'the-first-shoal', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-channel', 'east', 'the-second-shoal', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-second-shoal', 'door', 'The Second Shoal', 'Wider than the first and higher, with a spine of coarse stone down the middle that stays dry when everything else is under. There are bird tracks all over it and, in the middle, the print of a boot, filled with water, pointing east.', 0, 0, 'crossing', 0, 51, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-shoal', 'west', 'the-first-channel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-shoal', 'east', 'the-second-channel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-shoal', 'north', 'the-tern-scrape', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-tern-scrape', 'door', 'The Tern Scrape', 'A hollow in the shingle at the top of the shoal, lined with nothing at all, holding two eggs the colour of the stones around them. The birds are up and screaming the moment you are near it and they do not stop and they do not go away. Everything within half a mile now knows exactly where you are standing.', 0, 0, 'crossing', 0, 51, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tern-scrape', 'south', 'the-second-shoal', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-second-channel', 'door', 'The Second Channel', 'Deeper. Not much — thigh, at the middle — but deep enough that the water has your weight rather than the gravel, and the pack on your back becomes a sail. Four strides of it. It takes longer than four strides should.', 0, 0, 'crossing', 0, 52, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-channel', 'west', 'the-second-shoal', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-second-channel', 'east', 'the-long-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-long-bank', 'door', 'The Long Bank', 'The biggest of them: a bank of gravel a quarter of a mile long lying with the current, dry down its whole length, with weed dried to a crust along the tideline on both sides. Walking it is the easiest part of the ford and it goes on long enough that you start to relax.', 0, 0, 'crossing', 0, 53, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-bank', 'west', 'the-second-channel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-bank', 'east', 'the-third-channel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-bank', 'south', 'the-stranded-hull', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-bank', 'north', 'the-quicksand-flat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-stranded-hull', 'door', 'The Stranded Hull', 'A boat on the bank, upright, whole, sitting on the gravel as neatly as if somebody had put it there. The oars are shipped. There is a bailer wedged under the thwart. It cannot have got up here except at a height of water that would have covered everything you have walked across.', 0, 0, 'crossing', 0, 53, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stranded-hull', 'north', 'the-long-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-third-channel', 'door', 'The Third Channel', 'The main one. This is where the crossing''s water actually goes when it is going anywhere, and it is waist deep in the middle at the best of times, and there is a rope stretched across it on two posts for exactly that reason. The rope is old. It is also the only rope.', 0, 0, 'crossing', 0, 54, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-channel', 'west', 'the-long-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-channel', 'east', 'the-mid-ford', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-third-channel', 'south', 'the-drowned-withies', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-mid-ford', 'door', 'The Mid-Ford', 'The middle of the whole thing, on a shoal no bigger than a room, with water on every side and the shores equally far away. There is a post here with a crosspiece — not a marker, a REST: something to hold onto and stand behind while the water goes past you both ways.', 0, 0, 'crossing', 0, 55, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-ford', 'west', 'the-third-channel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-ford', 'east', 'the-fourth-channel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-ford', 'north', 'the-gull-stand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fourth-channel', 'door', 'The Fourth Channel', 'The water on this side runs the other way, which nobody warns you about and everybody discovers here. It is the same depth as the second and it is pushing you back the way you came instead of the way you were going, and the gravel is coarser and it grips better.', 0, 0, 'crossing', 0, 56, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fourth-channel', 'west', 'the-mid-ford', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fourth-channel', 'east', 'the-shell-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fourth-channel', 'north', 'the-tide-race', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shell-bank', 'door', 'The Shell Bank', 'A bank made of shell rather than gravel — cockle, mussel, razor, whole and broken, packed to a surface that crunches and gives. It is white enough to read a map by at dusk. There is a great deal of it and it is all the same three species, which means somebody was eating here for a very long time.', 0, 0, 'crossing', 0, 57, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shell-bank', 'west', 'the-fourth-channel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shell-bank', 'east', 'the-fifth-channel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shell-bank', 'north', 'the-midden', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-midden', 'door', 'The Midden', 'Where the shell bank rises into a proper mound, layered, cut into on one side by the water so that you can read down through it: shell, ash, shell, ash, a bone, shell. Somebody sat on this spot and ate shellfish for generations. There is nothing else of them anywhere.', 0, 0, 'crossing', 0, 57, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-midden', 'south', 'the-shell-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-midden', 'north', 'the-cockle-beds', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fifth-channel', 'door', 'The Fifth Channel', 'Shallow, wide, and full of weed that lies along the current in long green hair and wraps your ankles as you go through. It does not hold you. It only feels exactly like something holding you, once per stride, for forty yards.', 0, 0, 'crossing', 0, 58, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fifth-channel', 'west', 'the-shell-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fifth-channel', 'east', 'the-withy-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fifth-channel', 'south', 'the-eel-grass', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-withy-bank', 'door', 'The Withy Bank', 'The withies are thick here — a whole stand of them driven in a double row, marking the safe line where it bends. Half are new and half are grey and split, so this is maintained, and recently, and by somebody who is not here.', 0, 0, 'crossing', 0, 59, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-withy-bank', 'west', 'the-fifth-channel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-withy-bank', 'east', 'the-last-shoal', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-last-shoal', 'door', 'The Last Shoal', 'Gravel again, and the far bank close enough now to see individual stones on it. From here the ford looks like nothing — a mile of shallow water you could stroll across — and you know better than that now, and the knowing is the only thing you have brought over that you did not carry in.', 0, 0, 'crossing', 0, 60, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-shoal', 'west', 'the-withy-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-last-shoal', 'east', 'the-ford-landing', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ford-landing', 'door', 'The Ford Landing', 'A shelf of shingle where the ford comes ashore, with a hard of laid stone at the top of it and cart-ruts leading away east. It is the least dramatic arrival possible: no arch, no bench, no marker. Somebody with a load came this way often enough to cut ruts, and they never once felt like commemorating it.', 0, 0, 'crossing', 0, 61, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ford-landing', 'west', 'the-last-shoal', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ford-landing', 'east', 'the-cart-ruts', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-drowned-withies', 'door', 'The Drowned Withies', 'A stand of the marker withies out beyond the safe line, in water too deep to wade, bent over by the current and streaming. Somebody planted them in good faith when this was walkable ground. The channel moved. The withies did not.', 0, 0, 'crossing', 0, 54, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drowned-withies', 'north', 'the-third-channel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gull-stand', 'door', 'The Gull Stand', 'A shoal that gulls have taken, hundreds of them, standing all facing the same way into the wind and not one of them doing anything else. They lift when you come, in one enormous unhurried sheet, go round, and land again behind you facing the same way.', 0, 0, 'crossing', 0, 55, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gull-stand', 'south', 'the-mid-ford', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-eel-grass', 'door', 'The Eel Grass', 'A meadow of it in the shallows, growing in real soil rather than gravel, green and dense and moving all together. Things live in eel grass. You can see the wakes of them leaving as you come, small and fast and low, and none of them surface.', 0, 0, 'crossing', 0, 58, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eel-grass', 'north', 'the-fifth-channel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-quicksand-flat', 'door', 'The Quicksand Flat', 'Ground that looks exactly like the shoals and is not: fine grey sand, wet through, standing water on it in sheets that do not drain. A stick pushed into it goes in to the hand. Somebody has fenced the near edge with three withies and a length of rope, which is either a warning or a boundary.', 0, 0, 'crossing', 0, 53, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quicksand-flat', 'south', 'the-long-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-net-stakes', 'door', 'The Net Stakes', 'A second fixed engine, out on the flats: two long converging lines of stakes leading to a pound at the point, so the tide walked the fish down the funnel and left them in the trap. The stakes stand. The netting has gone entirely, and the funnel now catches only weed and light.', 0, 0, 'crossing', 0, 49, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-net-stakes', 'north', 'the-first-shoal', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cockle-beds', 'door', 'The Cockle Beds', 'Sand rather than gravel, and pocked all over with the little paired holes of things breathing under it. Rake it and they come up in handfuls. This is the most reliable food on the whole crossing and it is available exactly as often as the ford is, which is the same thing said twice.', 0, 0, 'crossing', 0, 57, -2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cockle-beds', 'south', 'the-midden', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-tide-race', 'door', 'The Tide Race', 'Where the ford''s water finally meets the channel''s, and the two disagree. A line of standing waves marks it, holding position while the water pours through them, and the noise is constant and unignorable and can be heard from every shoal on the ford.', 0, 0, 'crossing', 0, 56, -1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tide-race', 'south', 'the-fourth-channel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-rope-run', 'door', 'The Rope Run', 'The rope leaves the stage and goes out over the deep, sagging to touch the water at the middle and rising again beyond. Hand over hand along it is possible for exactly as long as your arms last and no longer, and the middle of it is under water, so it is not possible at all.', 0, 0, 'crossing', 0, 51, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rope-run', 'west', 'the-channel-brink', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rope-run', 'east', 'the-green-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rope-run', 'north', 'the-drowned-mooring', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-green-water', 'door', 'The Green Water', 'Where the bottom drops away. The colour of the water changes in a hard line you can stand on the edge of and look at — grey shallows behind, green deep in front, and the green does not lighten again anywhere you can see. This is the first water above ground that is over your head.', 0, 0, 'crossing', 0, 52, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-green-water', 'west', 'the-rope-run', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-green-water', 'east', 'the-ferry-boat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-green-water', 'north', 'the-cold-spring', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-green-water', 'south', 'the-deep-mark', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ferry-boat', 'door', 'The Ferry Boat', 'The boat is here. Broad, flat-bottomed, tarred, with the rope running through a ring at bow and stern so it cannot go anywhere but across. There is water in the bottom of it and a bailer, and the bailer has been used recently enough to still be wet.', 0, 0, 'crossing', 0, 53, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferry-boat', 'west', 'the-green-water', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferry-boat', 'east', 'the-mid-channel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferry-boat', 'south', 'the-eel-lines', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-mid-channel', 'door', 'The Mid-Channel', 'The deepest water in the crossing, and from the middle of it both shores are a long way off and the rope is the only thing connecting anything to anything. It goes down into the water ahead of you and comes up out of it behind. Whatever is below is below by a distance that does not bear thinking about.', 0, 0, 'crossing', 0, 54, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-channel', 'west', 'the-ferry-boat', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-channel', 'east', 'the-far-rope-stage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-channel', 'down', 'the-under-rope', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-channel', 'south', 'the-weed-raft', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mid-channel', 'north', 'the-slack', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-under-rope', 'door', 'Under the Rope', 'Below the surface the rope goes on down and the light goes green and then brown, and there is a shape down here — a second rope, or a chain, going off at an angle from the main one toward something on the bottom that is too regular to be stone.', 0, 0, 'crossing', 0, 55, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-rope', 'up', 'the-mid-channel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-far-rope-stage', 'door', 'The Far Rope Stage', 'The stage on the eastern bank, twin to the one you left: bollard, block, fend-off post, all of it maintained to exactly the same standard, which is to say maintained. The rope is made fast here to a ring set in living rock.', 0, 0, 'crossing', 0, 55, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-rope-stage', 'west', 'the-mid-channel', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-rope-stage', 'east', 'the-far-ferry-steps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-far-ferry-steps', 'door', 'The Far Ferry Steps', 'Steps cut up the eastern bank from the water, worn into scoops in the middle of each tread. At the top there is a bench, and a place where a lantern was, and a view back across the channel to the ferry house that is exactly the view from the ferry house, reversed.', 0, 0, 'crossing', 0, 56, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-ferry-steps', 'west', 'the-far-rope-stage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-ferry-steps', 'east', 'the-far-hard', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-ferry-steps', 'south', 'the-boat-house', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-ferry-steps', 'north', 'the-ferryman-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-far-hard', 'door', 'The Far Hard', 'The eastern ramp: laid stone into the water, grooved by keels, greener below the line and whiter above. Everything about it says the ferry ran both ways constantly for a very long time, and that whoever ran it cared about the stone at both ends equally.', 0, 0, 'crossing', 0, 57, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-hard', 'west', 'the-far-ferry-steps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-hard', 'east', 'the-tar-shed', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-hard', 'north', 'the-warping-post', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-drowned-mooring', 'door', 'The Drowned Mooring', 'Off the near stage: a line of mooring posts going out into the channel, of which the first three stand above water and the rest are visible below it, going down in a line into the green until they are only a suggestion. The channel was shallower here once. It is not now.', 0, 0, 'crossing', 0, 51, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drowned-mooring', 'south', 'the-rope-run', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-eel-lines', 'door', 'The Eel Lines', 'A long line strung between two stakes in the deep water off the boat''s course, with droppers every yard and a hook on every dropper. It is set, it is baited with something that has been down there a while, and it is not yours. Somebody is working this channel.', 0, 0, 'crossing', 0, 53, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eel-lines', 'north', 'the-ferry-boat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cold-spring', 'door', 'The Cold Spring', 'A place in the channel''s edge where fresh water comes up through the salt, and you can see it: a shimmer, a boil at the surface, and a patch where the weed grows differently. It is drinkable if you can get your face to the right part of it, and everything that lives in the channel knows exactly where it is.', 0, 0, 'crossing', 0, 52, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cold-spring', 'south', 'the-green-water', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boat-house', 'door', 'The Boat House', 'On the far bank above the stage, a shed of tarred board with a slipway running out of it, big enough for one boat and a man to work round it. There is a second boat in here, upside down on trestles, holed amidships and half-mended, with the tools still laid out along the keel.', 0, 1, 'crossing', 0, 56, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boat-house', 'north', 'the-far-ferry-steps', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boat-house', 'east', 'the-oar-store', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-signal-mast', 'door', 'The Signal Mast', 'A mast on the eastern bank with a yard and two blocks and a rotten halyard, for hoisting a shape that told the far side whether the boat was coming. There is a locker at the foot of it with the shapes still in it: a black ball, a black cone, a red diamond gone pink.', 0, 0, 'crossing', 0, 57, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-signal-mast', 'north', 'the-oar-store', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-weed-raft', 'door', 'The Weed Raft', 'A mat of cut weed and driftwood the current has pushed into the channel''s slack corner and pinned there, acres of it, thick enough to walk on in some places and exactly not thick enough in others, and there is no way to tell which is which from the surface.', 0, 0, 'crossing', 0, 54, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-weed-raft', 'north', 'the-mid-channel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ferryman-stone', 'door', 'The Ferryman''s Stone', 'A slab set upright on the eastern bank above the steps, with a name on it and two dates that are not far apart, and below them a line about the water. It faces the channel. Whoever set it up wanted him to go on looking at the crossing he did not get across.', 0, 0, 'crossing', 0, 56, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferryman-stone', 'south', 'the-far-ferry-steps', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-deep-mark', 'door', 'The Deep Mark', 'A stone post at the head of the green water with depths cut into it in bands, the deepest band well above the top of the post — which means the cutter ran out of post before he ran out of water, and marked that fact by cutting the last band on the underside of the cap.', 0, 0, 'crossing', 0, 52, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-mark', 'north', 'the-green-water', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-slack', 'door', 'The Slack', 'The one place in the channel where the current stops, in the lee of a spur of rock, and the water simply stands. Everything the channel is carrying arrives here eventually and turns slowly in a circle. It is the calmest water in the crossing and it is full of things that used to belong to people.', 0, 0, 'crossing', 0, 54, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-slack', 'south', 'the-mid-channel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-far-noust', 'door', 'The Far Noust', 'A boat-shaped hollow above the eastern tideline, stone-lined, the twin of the empty one on the western shore. There is a boat in this one, upside down, tarred, sound, and far too heavy for one person to move an inch.', 0, 0, 'crossing', 0, 58, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-noust', 'south', 'the-tar-shed', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-warping-post', 'door', 'The Warping Post', 'A massive post on the eastern hard with a groove worn all the way round it at chest height, where a rope was taken round to haul boats up out of the water. The groove is a hand deep. That is not one boat. That is every boat, for a lifetime.', 0, 0, 'crossing', 0, 57, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-warping-post', 'south', 'the-far-hard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-oar-store', 'door', 'The Oar Store', 'A rack under the boat house eaves holding six oars, blades up, all different lengths and all of them made for the same rowlock. Five are grey and cracked. One is not, and it has been used, and there is fresh water dripping off the blade of it.', 0, 0, 'crossing', 0, 57, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oar-store', 'west', 'the-boat-house', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-oar-store', 'south', 'the-signal-mast', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-first-eyot', 'door', 'The First Eyot', 'An island of solid ground the size of a barn, standing a foot above the reed, with three willows on it and a fire-ring under them that has been used a great many times by a great many different people. This is where everybody stops before going in, and everybody has left something.', 0, 1, 'crossing', 0, 47, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-eyot', 'north', 'the-reed-gate', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-eyot', 'south', 'the-brushwood-causey', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-first-eyot', 'east', 'the-otter-run', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-otter-run', 'door', 'The Otter Run', 'A slide in the mud from the water up over the eyot''s flank and down the other side, polished, used, and not by people. There are fish scales trodden into the top of it and a smell like a wet dog and old pennies.', 0, 0, 'crossing', 0, 48, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-otter-run', 'west', 'the-first-eyot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-brushwood-causey', 'door', 'The Brushwood Causey', 'Bundles of cut willow laid crosswise and pinned with stakes, sunk a hand under the mud so that you walk on a path you cannot see and find by feel and by the two lines of stakes on either side. Most of the stakes are there.', 0, 0, 'crossing', 0, 47, 14);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brushwood-causey', 'north', 'the-first-eyot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-brushwood-causey', 'south', 'the-hurdle-eyot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hurdle-eyot', 'door', 'The Hurdle Eyot', 'An island fenced all round with woven hurdles gone silver with weather, and inside the fence, nothing at all — no house, no hearth, no pen. Somebody enclosed an acre of marsh island and then never used it, and the fence is in better repair than anything else out here.', 0, 0, 'crossing', 0, 47, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hurdle-eyot', 'north', 'the-brushwood-causey', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hurdle-eyot', 'south', 'the-mud-causey', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hurdle-eyot', 'east', 'the-hurdle-store', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hurdle-eyot', 'west', 'the-sunken-hurdles', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hurdle-store', 'door', 'The Hurdle Store', 'A stack of spare hurdles under a lean-to on the eyot''s east side, forty or fifty of them, cut and woven and stacked and never put up. The willow is still springy. Whoever made these expected to need them, and the expecting is the only thing left of them.', 0, 0, 'crossing', 0, 48, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hurdle-store', 'west', 'the-hurdle-eyot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sunken-hurdles', 'door', 'The Drowned Hurdles', 'The fence goes on off the island''s west end and out into the water, three panels of it standing in mud with the tops just clear, going nowhere. Either the island was bigger or the fence was more ambitious. Both are possible and neither is comforting.', 0, 0, 'crossing', 0, 46, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunken-hurdles', 'east', 'the-hurdle-eyot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-mud-causey', 'door', 'The Mud Causey', 'The stakes stop and the causey does not, and for thirty yards the only way to know you are on it is that you have not yet gone in past the knee. There is a way to walk this and it involves keeping your weight back and testing forward, and everybody works it out in the first ten yards or the first fall.', 0, 0, 'crossing', 0, 47, 16);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mud-causey', 'north', 'the-hurdle-eyot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mud-causey', 'south', 'the-chapel-eyot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mud-causey', 'east', 'the-quaking-turf', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-chapel-eyot', 'door', 'The Chapel Eyot', 'The biggest of the islands and the only one with a building on it: a chapel of one room, stone, roofless, with the altar slab still in place and a stone bench round three walls. It faces east across the marsh at the mountain. People stopped here on the way over, every time, for a very long time.', 0, 1, 'crossing', 0, 47, 17);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-eyot', 'north', 'the-mud-causey', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-eyot', 'south', 'the-long-causey', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-eyot', 'east', 'the-graves', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-eyot', 'west', 'the-landing-stage', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-graves', 'door', 'The Graves', 'Behind the chapel, forty low humps in the turf in rough rows, unmarked but for a stone at the head of each one no bigger than a fist. Nobody carried a body out here. These are people who did not get across, laid where the marsh gave them back.', 0, 0, 'crossing', 0, 48, 17);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-graves', 'west', 'the-chapel-eyot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-landing-stage', 'door', 'The Landing Stage', 'A stone jetty on the chapel eyot''s west side, running out into a channel deep enough to float a boat, with a ring and a step. Whoever kept the chapel was supplied by water, not by the causeys, which says something about how much they trusted them.', 0, 0, 'crossing', 0, 46, 17);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-landing-stage', 'east', 'the-chapel-eyot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-landing-stage', 'north', 'the-chapel-channel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-chapel-channel', 'door', 'The Chapel Channel', 'Open water between the eyots, still and brown and deeper than it looks, with the reed standing in it on both sides. There is no way across here and no bridge and nothing to hold. It is here to be gone round, and the going round is most of what the eyots cost you.', 0, 0, 'crossing', 0, 46, 16);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-channel', 'south', 'the-landing-stage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-chapel-channel', 'east', 'the-decoy-pipe', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-long-causey', 'door', 'The Long Causey', 'The best-built thing in the marsh: a proper stone causey, two feet proud, with a drainage gap every twenty yards and cut kerbs on both sides. It runs dead straight for a quarter of a mile and it is a pleasure to walk, and it stops, without warning or apology, in the middle of the reed.', 0, 0, 'crossing', 0, 47, 18);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-causey', 'north', 'the-chapel-eyot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-causey', 'south', 'the-causey-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-long-causey', 'west', 'the-old-boat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-causey-end', 'door', 'The Causey End', 'Where the good stone stops. The last kerb is cut square and finished, and beyond it is mud with reed growing out of it, and there is no rubble and no fallen work — this was not destroyed, it was ABANDONED, mid-course, by people who meant to come back with more stone.', 0, 0, 'crossing', 0, 47, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-causey-end', 'north', 'the-long-causey', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-causey-end', 'east', 'the-plank-run', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-causey-end', 'south', 'the-reed-maze', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-plank-run', 'door', 'The Plank Run', 'Somebody''s answer to the causey stopping: planks, on trestles, running east through the reed, laid by eye and repaired in a dozen hands. It bounces. Where the trestles have gone the plank is held up by the mud alone, and you can tell which ones those are by the give. It ends in standing reed, at a trestle with no plank on it, forty yards short of anywhere.', 0, 0, 'crossing', 0, 48, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plank-run', 'west', 'the-causey-end', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-reed-maze', 'door', 'The Reed Maze', 'Reed over your head in every direction and a path that forks and forks again with no way to tell which fork is the way and which is where somebody once went to cut. There is no view. There is no sky worth the name. There is the sound of open water, from a direction that keeps changing.', 0, 0, 'crossing', 0, 47, 20);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-reed-maze', 'north', 'the-causey-end', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-reed-maze', 'south', 'the-cut-reed', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-reed-maze', 'east', 'the-reed-fork', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cut-reed', 'door', 'The Cut Reed', 'A stand that has been harvested, the stubble sharp as a hedge of nails underfoot and the standing crop making a wall on three sides. The cutting is old but the pattern is legible: they worked in strips, and the strips run east, and following them is the first sensible piece of navigation the marsh has offered.', 0, 0, 'crossing', 0, 47, 21);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut-reed', 'north', 'the-reed-maze', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut-reed', 'east', 'the-cutters-eyot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-reed-fork', 'door', 'The Reed Fork', 'The path splits around a stand of reed too thick to push through, and both ways look identical, and both ways are used. One goes to the cutters'' island. The other goes to open water and stops, and nobody has ever marked which is which.', 0, 0, 'crossing', 0, 48, 20);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-reed-fork', 'west', 'the-reed-maze', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-reed-fork', 'south', 'the-cutters-eyot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-reed-fork', 'east', 'the-dead-end', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dead-end', 'door', 'The Dead End', 'The path opens onto brown water and finishes. There is a stake here with a rag on it, tied by somebody who came this way, worked out their mistake, and wanted the next person to know sooner than they had. The rag is one of very few kindnesses in this world.', 0, 0, 'crossing', 0, 49, 20);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-end', 'west', 'the-reed-fork', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cutters-eyot', 'door', 'The Cutters'' Eyot', 'An island of trodden ground and reed-stacks, with a low turf hut, a whetstone on a post, and a great many reed-hooks pushed into the turf blade-down in a row. This is a working place. The stacks are graded by year and the oldest is grey and the newest is gold.', 0, 1, 'crossing', 0, 48, 21);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cutters-eyot', 'west', 'the-cut-reed', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cutters-eyot', 'north', 'the-reed-fork', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cutters-eyot', 'south', 'the-hook-hut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cutters-eyot', 'east', 'the-stake-line', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hook-hut', 'door', 'The Hook Hut', 'Turf walls, a roof of reed on rafters of reed, one door and no window, and inside it is dry and dark and smells of cut sedge. There is a bed of reed against the wall and a stone for a hearth and, hung on a nail, a coat that would still keep the rain off.', 0, 1, 'crossing', 0, 48, 22);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hook-hut', 'north', 'the-cutters-eyot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-stake-line', 'door', 'The Stake Line', 'A line of stakes going east through open reed, driven at a stride''s spacing by somebody who counted their strides, and it is the single most useful object in the eyots. Follow the stakes and you get across. Lose them and you are in the marsh, which is a different problem entirely.', 0, 0, 'crossing', 0, 49, 21);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stake-line', 'west', 'the-cutters-eyot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stake-line', 'east', 'the-black-eyot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stake-line', 'south', 'the-eel-hut', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-black-eyot', 'door', 'The Black Eyot', 'Peat, not silt: an island of black ground standing higher than the rest, dry, hard, and carrying a stand of alder that has been there long enough to have fallen over twice and gone on growing. From the top of it you can see the mountain, the channel, the chapel roofless behind you, and how far there is left.', 0, 0, 'crossing', 0, 50, 21);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-eyot', 'west', 'the-stake-line', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-eyot', 'south', 'the-sunken-forest', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-eyot', 'east', 'the-tern-causey', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-sunken-forest', 'door', 'The Sunken Forest', 'Off the black eyot''s south shore, in the shallow water: stumps. Hundreds of them, black and hard, cut level by the water rather than by any axe, in rows and clusters that are obviously a wood. This was dry land with trees on it. The water is what happened next.', 0, 0, 'crossing', 0, 50, 22);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunken-forest', 'north', 'the-black-eyot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-tern-causey', 'door', 'The Tern Causey', 'Brushwood again, and this stretch is colonised — terns nest on the causey itself, in the gaps between the bundles, and they go up the moment you set foot on it and stay up, and dive at your head, and do not stop until you are off their ground.', 0, 0, 'crossing', 0, 51, 21);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tern-causey', 'west', 'the-black-eyot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tern-causey', 'east', 'the-shell-eyot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tern-causey', 'north', 'the-fowlers-hide', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shell-eyot', 'door', 'The Shell Eyot', 'An island made of shell — the same midden material as the ford''s, but here it is the whole island, a mound of it thirty yards across standing three feet proud of the marsh and white as bone. Nothing grows on it. Nothing has ever grown on it.', 0, 0, 'crossing', 0, 52, 21);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shell-eyot', 'west', 'the-tern-causey', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shell-eyot', 'east', 'the-salt-causey', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shell-eyot', 'north', 'the-shell-scar', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shell-scar', 'door', 'The Shell Scar', 'Where the water has cut into the shell mound and laid its layers open: shell, shell, a band of ash and burnt bone, shell, and at the very bottom, dark earth with flints in it. You can put your hand on the bottom of it and be touching the ground somebody stood on before any of this was water.', 0, 0, 'crossing', 0, 52, 20);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shell-scar', 'south', 'the-shell-eyot', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-salt-causey', 'door', 'The Salt Causey', 'The last of the made ways: stone again, poorly, laid by somebody without the long causey''s skill or budget, running east over ground that is more salt than mud. Samphire grows in the gaps between the stones. Everything from here on tastes of the sea rather than the marsh.', 0, 0, 'crossing', 0, 53, 21);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-causey', 'west', 'the-shell-eyot', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-causey', 'east', 'the-salt-marsh', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-causey', 'north', 'the-heron-tree', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-salt-marsh', 'door', 'The Salt Marsh', 'The reed gives out and the ground opens into a flat of salt marsh, cut all over by creeks with vertical mud banks — no cover, no reed, no path, and a horizon in every direction. The creeks are the problem: they are deeper than they look and they run where they like.', 0, 0, 'crossing', 0, 54, 21);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-marsh', 'west', 'the-salt-causey', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-marsh', 'east', 'the-creek-crossing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-marsh', 'north', 'the-samphire-flat', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-samphire-flat', 'door', 'The Samphire Flat', 'Acres of it, green and jointed and growing in the bare mud where nothing else will, so thick in places you cannot see the ground. It is food. It is good food, and it is the only thing in the eyots that is straightforwardly a gift, and it comes back every time you cut it.', 0, 0, 'crossing', 0, 54, 20);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-samphire-flat', 'south', 'the-salt-marsh', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-creek-crossing', 'door', 'The Creek Crossing', 'The biggest of the creeks, twenty feet across, with mud banks going down sheer and the water at the bottom moving fast. There is a plank. It is one plank, on the mud, laid across, and it is longer than it needs to be, which means somebody measured this creek at a worse moment than the one you are looking at.', 0, 0, 'crossing', 0, 55, 21);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-creek-crossing', 'west', 'the-salt-marsh', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-creek-crossing', 'east', 'the-marsh-hard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-marsh-hard', 'door', 'The Marsh Hard', 'Laid stone at last, a real hard going up out of the marsh onto the far bank, with a bollard and cart-ruts and the marks of a lot of traffic. The eyots let you go without ceremony. Behind you the whole marsh lies flat and green and looks like a field.', 0, 0, 'crossing', 0, 56, 21);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marsh-hard', 'west', 'the-creek-crossing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marsh-hard', 'north', 'the-hard-approach', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fowlers-hide', 'door', 'The Fowler''s Hide', 'A pit dug into the black eyot''s edge and roofed with cut reed, with a slot to see through at water level and a shelf inside worn smooth by elbows. A man lay in here for hours at a time, waiting for birds. The view through the slot is of open water and nothing else, and it is a very good place to see without being seen.', 0, 0, 'crossing', 0, 51, 20);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fowlers-hide', 'south', 'the-tern-causey', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-decoy-pipe', 'door', 'The Decoy Pipe', 'A curving ditch off the chapel channel, netted over on hoops, narrowing to a trap at the far end — a decoy, for taking duck in numbers. The hoops still stand. Most of the netting has gone, and what is left moves when the wind gets under it and looks, from the corner of the eye, like something walking under the net.', 0, 0, 'crossing', 0, 45, 16);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-decoy-pipe', 'east', 'the-chapel-channel', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-quaking-turf', 'door', 'The Quaking Ground', 'Turf that floats. It holds you, and it moves under you as it does, and if you stand still and shift your weight you can watch a wave go out across it for twenty yards. There is water under everything here and the only thing between you and it is a mat of root a hand thick.', 0, 0, 'crossing', 0, 48, 16);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-quaking-turf', 'west', 'the-mud-causey', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-old-boat', 'door', 'The Old Boat', 'A punt sunk in the reed off the long causey, flat-bottomed and open, with a quant pole still shipped along the inside of the gunwale. It is full of water and silt and there is a bird nesting in the bow, and it would float again with a day''s work and a way to get a day''s work out here.', 0, 0, 'crossing', 0, 46, 18);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-boat', 'east', 'the-long-causey', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-eel-hut', 'door', 'The Eel Hut', 'On stilts over the water off the cutters'' eyot: a plank shack the size of a bed, with a hatch in the floor and a rack of eel-traps on the wall, and a stove made from a broken pot. The hatch opens onto black water. This is a place somebody worked at night, on purpose, alone.', 0, 1, 'crossing', 0, 49, 22);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eel-hut', 'north', 'the-stake-line', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-heron-tree', 'door', 'The Heron Stand', 'A dead alder in open water off the shell eyot with six herons in it, standing at different heights, none of them moving. They do not go up as you pass. They turn their heads, all of them, in the same unhurried way, and go on standing there.', 0, 0, 'crossing', 0, 53, 20);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-heron-tree', 'south', 'the-salt-causey', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-far-strand', 'door', 'The Far Strand', 'Shingle and weed and the whole crossing lying behind you, and the sudden and specific relief of ground that is not going to be water later. The shore road runs north from here past every one of the landings in turn, and south it gives up being a road at all and goes down the coast toward the marsh.', 0, 0, 'crossing', 0, 63, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-strand', 'north', 'the-landing-arch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-strand', 'south', 'the-marsh-road', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-far-parting', 'door', 'The Far Parting of the Ways', 'The eastern twin of the Parting, and it has the same five-armed fingerpost, facing the other way. It says where each of the five comes ashore and it says which of them you can trust today, which it does by the oldest method available: a man used to stand here and turn the arms.', 0, 0, 'crossing', 0, 63, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-parting', 'north', 'the-boat-graves', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-parting', 'south', 'the-landing-arch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-parting', 'east', 'the-crossing-house', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bridge-landing', 'door', 'The Bridge Landing', 'Where the far arch comes down: proper road, proper kerbs, and a stone bollard at the end of the parapet worn shiny on top by however many hands took hold of it on the way off the bridge. Everybody touches it. You will touch it.', 0, 0, 'crossing', 0, 63, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bridge-landing', 'west', 'the-hard-standing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bridge-landing', 'south', 'the-toll-cottage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bridge-landing', 'north', 'the-far-tide-mark', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-toll-cottage', 'door', 'The Toll Cottage', 'A one-room house at the bridge''s landward end with a hatch in the wall and a bench outside it, and a chimney that has not smoked in a long while. The bridge was tolled from both ends, which tells you it was worth tolling, which tells you what the crossing used to be.', 0, 0, 'crossing', 0, 63, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-toll-cottage', 'north', 'the-bridge-landing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-toll-cottage', 'south', 'the-cart-shed', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-crossing-house', 'door', 'The Crossing House', 'A long low building of good stone facing the water, with a lamp burning over a hatch in the road-facing wall, a yard, a well, and stabling for beasts that have not been here in two hundred years. Whatever the arrangement is, it has not lapsed here either, and the keeper behind the hatch does not explain it.', 1, 0, 'crossing', 0, 64, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crossing-house', 'west', 'the-far-parting', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crossing-house', 'east', 'the-strand-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crossing-house', 'south', 'the-well-yard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-well-yard', 'door', 'The Well Yard', 'A cobbled yard behind the crossing house with a well-head in the middle of it, roofed, with a windlass and a chain and a bucket that comes up full of water clean enough to be worth the walk. This is the only sweet water within a mile of anywhere and everything on this shore knows it.', 0, 0, 'crossing', 0, 64, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-well-yard', 'north', 'the-crossing-house', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-well-yard', 'south', 'the-keepers-garden', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-strand-road', 'door', 'The Strand Road', 'The made road running north to south along the eastern shore, the twin of the one on the western bank, in the same repair and to the same drawing. It serves the crossings. It is the last piece of the institution''s work you will walk on.', 0, 0, 'crossing', 0, 65, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-road', 'west', 'the-crossing-house', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-road', 'north', 'the-boat-noust-east', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-road', 'south', 'the-salt-pans', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-road', 'east', 'the-shingle-rise', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boat-noust-east', 'door', 'The Eastern Noust', 'Another boat-shaped hollow above the tideline, lined with stone, and this one is occupied: a boat, upside down, tarred, whole, with stones on the bilge to hold her. Two nousts on two shores and one boat between them, and everything about the crossing is in that arithmetic.', 0, 0, 'crossing', 0, 65, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boat-noust-east', 'south', 'the-strand-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boat-noust-east', 'north', 'the-drying-frames', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-salt-pans', 'door', 'The Salt Pans', 'Shallow rectangular pans cut into the clay above the tideline, fed by a channel with a wooden gate, where the water was let in and left to go. The pans are dry and crusted white at the edges. Salt is why anybody was ever out here doing anything, and this is where it was made.', 0, 0, 'crossing', 0, 65, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-pans', 'north', 'the-strand-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-pans', 'south', 'the-pan-house', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-pans', 'east', 'the-salt-store', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-pan-house', 'door', 'The Pan House', 'A shed over the biggest pan with the iron pan itself still in it, six feet across, sitting on a brick flue, warped and rusted through in one corner. Boiling was the last stage and the fuel was the expensive part. There is a stack of cut peat by the door, still dry.', 0, 1, 'crossing', 0, 65, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pan-house', 'north', 'the-salt-pans', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-salt-store', 'door', 'The Salt Store', 'A stone building with no windows and a raised wooden floor, built to keep salt dry, which on this coast is the hardest thing anybody ever tried to do. The floor is sound. There is a drift of grey salt in one corner, hard as rock, and a wooden scoop lying on it.', 0, 0, 'crossing', 0, 66, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-store', 'west', 'the-salt-pans', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salt-store', 'south', 'the-anchor-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shingle-rise', 'door', 'The Shingle Rise', 'The road leaves the shore and climbs the storm beach — a great bank of shingle thrown up by weather over centuries, twenty feet high, with the road cut through it in a notch. From the top of the notch you see the mountain properly for the first time, and it is a great deal closer than it was.', 0, 0, 'crossing', 0, 66, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shingle-rise', 'west', 'the-strand-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shingle-rise', 'east', 'the-thrift-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-thrift-bank', 'door', 'The Thrift Bank', 'The landward slope of the storm beach, covered in sea-pink growing out of bare stone in cushions, pink and grey and going on for as far as the beach does. It is the first pretty thing since the wood, and it is growing on a bank made entirely of what the sea has thrown away.', 0, 0, 'crossing', 0, 67, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thrift-bank', 'west', 'the-shingle-rise', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thrift-bank', 'east', 'the-shingle-stair', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thrift-bank', 'north', 'the-fisher-huts', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-thrift-bank', 'south', 'the-storm-line', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fisher-huts', 'door', 'The Fisher Huts', 'Four huts in a row in the lee of the storm beach, built of upturned boats on stone footings — hulls for roofs, doors cut in the transoms. Three are empty and open. The fourth has its door shut, and there is a stone against it on the outside, which is how you leave a place you mean to come back to.', 0, 1, 'crossing', 0, 67, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fisher-huts', 'south', 'the-thrift-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fisher-huts', 'east', 'the-net-loft', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-net-loft', 'door', 'The Net Loft', 'A shed on staddle stones with a plank floor, hung wall to wall with nets on pegs — herring nets, seine, a trammel with three walls of mesh — every one of them mended and rolled and hung properly. Whoever kept this gear was good at their work and expected to use it again.', 0, 0, 'crossing', 0, 68, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-net-loft', 'west', 'the-fisher-huts', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shingle-stair', 'door', 'The Shingle Stair', 'A stair of laid stone going up the last of the beach onto the headland, and at the top of it the road stops being the institution''s and becomes a track. Ahead and above: the mountain, filling the sky from one side to the other, with the track going up into it and out of sight. There is a stone seat here, facing it.', 0, 1, 'crossing', 0, 68, 9);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shingle-stair', 'west', 'the-thrift-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-strand-track', 'door', 'The Strand Track', 'South from the parting, along the shore below the marsh, a track of trodden shingle and no more. It serves the eyots and the salt marsh and the people who worked them, and it has been walked by more feet than the road has, and made by none of them.', 0, 0, 'crossing', 0, 56, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-track', 'south', 'the-cockle-strand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-track', 'east', 'the-eel-staithe', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-strand-track', 'west', 'the-bothy-of-the-crossing', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-drying-frames', 'door', 'The Drying Frames', 'Rows of wooden frames on the shingle above the tide, tarred and standing, where fish and nets were hung to dry in the wind. Perhaps two hundred of them. They creak all together when the wind comes off the water, which it always is.', 0, 0, 'crossing', 0, 65, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drying-frames', 'south', 'the-boat-noust-east', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drying-frames', 'east', 'the-limpet-rocks', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drying-frames', 'north', 'the-smoke-house', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-smoke-house', 'door', 'The Smoke House', 'A low stone building with no chimney and a door that fits badly on purpose, and inside, tiers of rods running wall to wall, black with two centuries of smoke, and the smell still in the stone hard enough to taste. There is a bed of old ash on the floor, and a scatter of oak chips.', 0, 1, 'crossing', 0, 65, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-smoke-house', 'south', 'the-drying-frames', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-limpet-rocks', 'door', 'The Limpet Rocks', 'A reef running out from the far strand, exposed at low water, with limpets on it so thick the rock is grey with them. Everything that eats shellfish comes here and the shell-scatter above the tideline says so: broken, opened, and dropped by things with hands and things without.', 0, 0, 'crossing', 0, 66, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-limpet-rocks', 'west', 'the-drying-frames', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-far-tide-mark', 'door', 'The Far Tide Mark', 'The eastern twin of the marker post: a scale cut up a post, taller than a man, with a bracket at the top. This one has its lantern — glass gone, frame intact, and a stub of candle in it that has been rained on and has run down the side and set again.', 0, 0, 'crossing', 0, 63, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-tide-mark', 'south', 'the-bridge-landing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-far-tide-mark', 'north', 'the-shepherds-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-keepers-garden', 'door', 'The Keeper''s Garden', 'Behind the well yard, a walled plot the size of two rooms, dug in beds, with a bean-frame still standing and a fruit tree trained flat against the south wall. Somebody grew food out here on ground they had to make themselves, and something has been at the beans recently.', 0, 0, 'crossing', 0, 64, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-keepers-garden', 'north', 'the-well-yard', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cart-shed', 'door', 'The Cart Shed', 'Open-fronted, three bays, with the wreck of one cart in the first bay and nothing at all in the other two. There are wheel-ruts running into all three, so this was full once, and the ruts leading out of the empty bays are deeper than the ones leading in.', 0, 0, 'crossing', 0, 63, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cart-shed', 'north', 'the-toll-cottage', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cart-shed', 'south', 'the-ferry-strand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-anchor-stone', 'door', 'The Anchor Stone', 'A block of granite on the strand with a hole bored clean through it, big enough to put your arm in, and a rope''s-worth of wear on the inside of the hole. It is far too heavy to have been brought here and there is no granite in this country, so it came by water, as ballast, and stayed.', 0, 0, 'crossing', 0, 66, 11);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-anchor-stone', 'north', 'the-salt-store', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bothy-of-the-crossing', 'door', 'The Crossing Bothy', 'Off the strand track: a stone bothy with a slate roof, a door that shuts, a hearth that draws, and a bed-shelf for four. It belongs to nobody and it is for anybody, and there is a rule about it written on the lintel in a hand that meant it: LEAVE IT DRY, LEAVE IT FUELLED.', 0, 1, 'crossing', 0, 55, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bothy-of-the-crossing', 'east', 'the-strand-track', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-storm-line', 'door', 'The Storm Line', 'The top of the shingle bank, where the biggest weather leaves its mark: a ridge of weed and timber and one whole tree, bleached white, lying along the crest as neatly as if it had been placed. This is how high the water has been. It is a great deal higher than anything you crossed today.', 0, 0, 'crossing', 0, 67, 10);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-storm-line', 'north', 'the-thrift-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ford-corner', 'door', 'The Ford Corner', 'The northern end of the shore road, where it turns out of itself and goes west down the cart-ruts to the flats. There is nothing here but the turn, a heap of road-stone gone to grass, and the particular emptiness of the least-used end of a road.', 0, 0, 'crossing', 0, 63, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ford-corner', 'south', 'the-drove-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ford-corner', 'west', 'the-cart-ruts', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cart-ruts', 'door', 'The Cart Ruts', 'The track down off the gravel flats, worn into two parallel troughs so deep that a cart could not have left them if it wanted to. Water stands in the bottom of both. Between them the crown of the track is untouched grass, which is the shape every old road ends up as.', 0, 0, 'crossing', 0, 62, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cart-ruts', 'east', 'the-ford-corner', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cart-ruts', 'west', 'the-ford-landing', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-drove-road', 'door', 'The Drove Road', 'A wide stretch of the shore road with a verge on both sides broad enough to graze a herd on overnight, which is exactly what it is for: beasts came over the ford, and beasts have to stop somewhere before they are worth anything. The grass on the verges is a different grass from the grass anywhere else.', 0, 0, 'crossing', 0, 63, 1);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drove-road', 'north', 'the-ford-corner', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-drove-road', 'south', 'the-shepherds-stone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shepherds-stone', 'door', 'The Shepherd''s Stone', 'A flat-topped boulder at the roadside with a hollow worn in the top of it, and a smaller stone beside it worn to a seat. Somebody sat here for a great many hours watching something graze. There are initials cut into the seat stone, three sets, one of them very much older than the others.', 0, 0, 'crossing', 0, 63, 2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shepherds-stone', 'north', 'the-drove-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shepherds-stone', 'south', 'the-far-tide-mark', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hard-standing', 'door', 'The Hard Standing', 'Between the bridge''s landing and the water: a levelled place where loads were shifted off carts before the bridge took them, floored with rammed chalk and edged with kerbs. There are wheel-ruts in it a hand deep, and they all point the same two ways.', 0, 0, 'crossing', 0, 62, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hard-standing', 'east', 'the-bridge-landing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hard-standing', 'west', 'the-wrack-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wrack-bank', 'door', 'The Wrack Bank', 'A bank of weed thrown up and rotting under the bridge''s landward end, deep enough to walk on and warm enough inside to steam on a cold morning. Everything that eats flies lives here. It is the least pleasant hundred yards on either bank and the road runs straight through the middle of it.', 0, 0, 'crossing', 0, 61, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wrack-bank', 'east', 'the-hard-standing', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wrack-bank', 'west', 'the-shingle-spit', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-shingle-spit', 'door', 'The Shingle Spit', 'A tongue of shingle running out into the water, thrown up where the bridge''s piers slow the current, growing a little every year. There is a line of stakes down the middle of it that used to be a fence on dry land and is now a fence in the sea.', 0, 0, 'crossing', 0, 60, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shingle-spit', 'east', 'the-wrack-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-shingle-spit', 'west', 'the-bridge-strand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-bridge-strand', 'door', 'The Bridge Strand', 'Directly under the bridge''s landward end, in the shadow of the far arch, with the piers marching away west over the water. From down here you can see the whole span of what is missing, and the underside of the stonework, and how much of the arch is holding on by being an arch.', 0, 0, 'crossing', 0, 59, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bridge-strand', 'east', 'the-shingle-spit', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bridge-strand', 'west', 'the-far-arch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ferry-strand', 'door', 'The Ferry Strand', 'Where the ferry''s road meets the shore road. The water is narrowest here, which is the entire reason a rope was ever stretched across it, and the reason the ferry lands further west than anything else and has the longest walk inland of the five.', 0, 0, 'crossing', 0, 63, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferry-strand', 'north', 'the-cart-shed', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferry-strand', 'south', 'the-boat-graves', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferry-strand', 'west', 'the-ferry-lane', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-ferry-lane', 'door', 'The Ferry Lane', 'A sunken lane running west toward the water between banks higher than your head, cut down into the ground by nothing but use. It is the road every passenger the ferry ever carried walked up, and it is worn a full four feet below the field on either side of it.', 0, 0, 'crossing', 0, 62, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferry-lane', 'east', 'the-ferry-strand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-ferry-lane', 'west', 'the-passengers-rest', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-passengers-rest', 'door', 'The Passengers'' Rest', 'A stone shelter at the roadside, open on the road side, roofed, with a bench along the back wall and a slot window facing the water so that you could see the boat coming without getting wet waiting for it. The bench is worn into hollows in four places.', 0, 1, 'crossing', 0, 61, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-passengers-rest', 'east', 'the-ferry-lane', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-passengers-rest', 'west', 'the-toll-board', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-toll-board', 'door', 'The Toll Board', 'A board on two posts beside the lane, boarded and battened and painted, and the paint has gone except where it was thickest, which was the numbers. What survives is a column of figures with nothing to say what they were for. Somebody has scratched a fifth line under the last one, freehand, and doubled it.', 0, 0, 'crossing', 0, 60, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-toll-board', 'east', 'the-passengers-rest', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-toll-board', 'west', 'the-capstan-round', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-capstan-round', 'door', 'The Capstan Round', 'A circle of hard-trodden ground with a capstan at the centre of it, timber, waist high, with six bar-holes and a groove worn round the base by the feet of the people who walked it. Boats were hauled up out of the water here by six men going round and round.', 0, 0, 'crossing', 0, 59, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-capstan-round', 'east', 'the-toll-board', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-capstan-round', 'west', 'the-tar-shed', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-tar-shed', 'door', 'The Tar Shed', 'An open shed of blackened board with a copper set in a brick surround and a stack of split wood beside it, for boiling the tar that everything on this coast is soaked in. The copper is empty and clean. The smell has got into the ground for ten feet in every direction.', 0, 0, 'crossing', 0, 58, 7);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tar-shed', 'east', 'the-capstan-round', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tar-shed', 'west', 'the-far-hard', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tar-shed', 'north', 'the-far-noust', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-boat-graves', 'door', 'The Boat Graves', 'Where the coast puts its dead boats: seven of them along the tideline below the road, in various stages of going back to the ground, ribs up, planks gone, the oldest of them only a stain in the shingle in the shape of a hull. Nobody broke these up for firewood, which on a coast this short of wood means something.', 0, 0, 'crossing', 0, 63, 8);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boat-graves', 'north', 'the-ferry-strand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boat-graves', 'south', 'the-far-parting', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-marsh-road', 'door', 'The Marsh Road', 'South of the strand the road stops being the institution''s: no kerbs, no camber, no metalling, just a way people have gone. It runs south and then west along the top of the salting, toward the marsh and the eyots and nothing else at all.', 0, 0, 'crossing', 0, 63, 12);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marsh-road', 'north', 'the-far-strand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marsh-road', 'south', 'the-samphire-turn', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-samphire-turn', 'door', 'The Samphire Turn', 'The track turns west here, off the shingle and onto the salting, because south of this point there is no ground worth the name for two miles. Samphire grows in the wheel-ruts, which tells you how often a wheel comes.', 0, 0, 'crossing', 0, 63, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-samphire-turn', 'north', 'the-marsh-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-samphire-turn', 'west', 'the-saltings-gate', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gull-flats', 'door', 'The Gull Flats', 'Open mud and open sky and a great many gulls standing on it all facing the same way into the wind, which is how you find out which way the wind is out here. They lift when you come and settle again behind you and the whole flock has forgotten you inside a minute.', 0, 0, 'crossing', 0, 61, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gull-flats', 'east', 'the-saltings-gate', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gull-flats', 'west', 'the-cockle-scars', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-saltings-gate', 'door', 'The Saltings Gate', 'A field gate on the track with no fence on either side of it any more, hung on one hinge and standing open, and worn smooth on the top rail where hands and elbows have rested on it. It stops nothing. People still go through it rather than round, which is most of what a gate is.', 0, 0, 'crossing', 0, 62, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-saltings-gate', 'east', 'the-samphire-turn', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-saltings-gate', 'west', 'the-gull-flats', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cockle-scars', 'door', 'The Cockle Scars', 'Raked ground going on for acres — cockle beds worked over so many times the mud is corrugated with it, and shell heaps above the tideline the size of cottages, white and grey and going back centuries. This fed people. It fed a lot of people for a very long time.', 0, 0, 'crossing', 0, 60, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cockle-scars', 'east', 'the-gull-flats', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cockle-scars', 'west', 'the-fowlers-track', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-fowlers-track', 'door', 'The Fowler''s Track', 'A causeway of faggots and mud a foot above the salting, laid to get a man and a gun out to the water without wading. It is springy underfoot and it complains, and the complaint carries a long way over flat ground, which is a poor quality in a fowler''s road.', 0, 0, 'crossing', 0, 59, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fowlers-track', 'east', 'the-cockle-scars', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fowlers-track', 'west', 'the-wildfowler', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fowlers-track', 'south', 'the-decoy-wood', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-wildfowler', 'door', 'The Wildfowler''s Stand', 'A hut of driftwood and turf on the marsh''s edge with a punt-gun stand at the front of it — a rest for a gun too big for a man to hold, aimed low over the water at where the birds sit. The gun is gone. The rest is here, and the arc it swings through is worn into the wood.', 0, 0, 'crossing', 0, 58, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wildfowler', 'east', 'the-fowlers-track', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wildfowler', 'west', 'the-eel-staithe', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-decoy-wood', 'door', 'The Decoy Wood', 'A dozen wind-bent willows in a clump on the only rise for a mile, planted on purpose to shelter a duck decoy, and the pipes of the decoy still curve away under the trees in rotted hoops. It is the only shade on this shore and everything that wants shade is in it.', 0, 0, 'crossing', 0, 59, 14);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-decoy-wood', 'north', 'the-fowlers-track', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-eel-staithe', 'door', 'The Eel Staithe', 'A landing of tarred planks on posts where the creek comes closest to the track, with eel-grigs stacked under it out of the light, a dozen of them, wicker, mended. Somebody keeps this gear the way somebody kept the net loft: properly, and recently.', 0, 0, 'crossing', 0, 57, 13);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eel-staithe', 'east', 'the-wildfowler', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-eel-staithe', 'west', 'the-strand-track', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-cockle-strand', 'door', 'The Cockle Strand', 'The track along the tideline going south toward the marsh proper. Cockle shell underfoot instead of shingle, and the going is soft, and the water is a long way out and coming back.', 0, 0, 'crossing', 0, 56, 14);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cockle-strand', 'north', 'the-strand-track', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cockle-strand', 'south', 'the-mud-shore', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-mud-shore', 'door', 'The Mud Shore', 'Shingle ends and mud begins, grey and slick and printed all over with birds. The track keeps to the top of it where the samphire starts, because the mud below will take a boot and keep it.', 0, 0, 'crossing', 0, 56, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mud-shore', 'north', 'the-cockle-strand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mud-shore', 'south', 'the-gutway', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-gutway', 'door', 'The Gutway', 'A creek runs out of the marsh across the track here and there is a bridge of one slab over it, worn hollow in the middle. The water in the gut runs out fast and comes in faster and is never the same width twice.', 0, 0, 'crossing', 0, 56, 16);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gutway', 'north', 'the-mud-shore', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-gutway', 'south', 'the-salting-edge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-salting-edge', 'door', 'The Salting Edge', 'Where the salt marsh proper begins: turf cut into by creeks, grazed short by something, standing a foot above the mud on a bank of its own making. The track runs along the top of the bank because there is nowhere else it could go.', 0, 0, 'crossing', 0, 56, 17);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salting-edge', 'north', 'the-gutway', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-salting-edge', 'south', 'the-creek-mouth', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-creek-mouth', 'door', 'The Creek Mouth', 'The biggest of the marsh creeks opening into the crossing, forty feet wide at the mouth and empty at low water — a canyon of mud with a stream in the bottom. There are staithe posts along the far side, so boats came up here, which means it is deeper than it looks when it is full.', 0, 0, 'crossing', 0, 56, 18);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-creek-mouth', 'north', 'the-salting-edge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-creek-mouth', 'south', 'the-marsh-strand', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-marsh-strand', 'door', 'The Marsh Strand', 'Track, marsh, water, and no other feature of any kind for as far as this goes. The reed is a green wall to the east and the crossing is a grey plain to the west and the sky is doing most of the work.', 0, 0, 'crossing', 0, 56, 19);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marsh-strand', 'north', 'the-creek-mouth', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-marsh-strand', 'south', 'the-hard-approach', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-hard-approach', 'door', 'The Hard Approach', 'The last of the shore track before the marsh''s own hard, running between the creek and the reed with barely room for both. The eyots come out here. Whatever you learned crossing them, this is where you stop needing it.', 0, 0, 'crossing', 0, 56, 20);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hard-approach', 'north', 'the-marsh-strand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-hard-approach', 'south', 'the-marsh-hard', NULL);
